get_price_display_settings.code:
use WebCommander\Sdk\Resources\Settings\PriceDisplaySettings\PriceDisplaySettings;

$response = PriceDisplaySettings::getPriceDisplaySettings($client);

$settings = $response->map['price_display_settings'];
echo 'price including tax: ', $settings['order_item']['price_including_tax']['enabled'] ? 'on' : 'off', PHP_EOL;
echo 'order total: ', $settings['order_summary']['order_total']['enabled'] ? 'on' : 'off', PHP_EOL;

patch_price_display_settings.code:
use WebCommander\Sdk\Resources\Settings\PriceDisplaySettings\PriceDisplaySettings;

$response = PriceDisplaySettings::patchPriceDisplaySettings($client, [
    'price_display_settings' => [
        'order_item' => ['price_including_tax' => ['enabled' => true, 'customize' => false]],
        'order_summary' => ['payment_surcharge' => ['enabled' => true, 'customize' => false]],
    ],
]);

$settings = $response->map['price_display_settings'];
echo $settings['order_item']['price_including_tax']['enabled'] ? 'true' : 'false', PHP_EOL;
echo $settings['order_summary']['payment_surcharge']['enabled'] ? 'true' : 'false', PHP_EOL;

get_price_display_settings_section.code:
use WebCommander\Sdk\Resources\Settings\PriceDisplaySettings\PriceDisplaySettings;

$response = PriceDisplaySettings::getPriceDisplaySettingsSection($client, 'order_item');

foreach ($response->map['order_item'] as $name => $block) {
    echo $name, $block['enabled'] ? ' on' : ' off', PHP_EOL;
}

patch_price_display_settings_section.code:
use WebCommander\Sdk\Resources\Settings\PriceDisplaySettings\PriceDisplaySettings;

$response = PriceDisplaySettings::patchPriceDisplaySettingsSection($client, 'order_item', [
    'order_item' => ['price_including_discount' => ['enabled' => true]],
]);

$block = $response->map['order_item']['price_including_discount'];
echo 'enabled: ', $block['enabled'] ? 'true' : 'false', PHP_EOL;
echo 'checkout: ', $block['scopes']['checkout'] ? 'true' : 'false', PHP_EOL;
